#!/usr/bin/env python3
"""
Round 186o (culprits-tiles-more), 5 October 2026.

holidays/culprits.geojson with nine more sourced holiday corporatizers
(21 in all). Written only if it differs.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, sys

FILES = {'holidays/culprits.geojson': ''}


def main():
    if not pathlib.Path("holidays").is_dir():
        sys.exit("round186o_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round186o_tiles: wrote {path}")
    if not changed:
        print("round186o_tiles: already applied")


if __name__ == "__main__":
    main()
